    private static final List<CollectibleDefinition> ALL = buildAll();

    private CollectibleDefinitions() {
    }

    public static List<CollectibleDefinition> all() {
        return ALL;
    }

    private static List<CollectibleDefinition> buildAll() {
        ArrayList<CollectibleDefinition> all = new ArrayList<>(RELICS.size() + POTIONS.size());
        all.addAll(RELICS);
        all.addAll(POTIONS);
        return List.copyOf(all);
    }

    private static CollectibleDefinition definition(String path, CollectibleKind kind, String texturePath) {
        return new CollectibleDefinition(ResourceLocation.fromNamespaceAndPath(Slaythespire.MODID, path), kind, ResourceLocation.fromNamespaceAndPath(Slaythespire.MODID, texturePath));
    }
